insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('004c3d43-a643-4255-adc7-5f05963bc6e9','ja','daehanminguk-clap-cheer','テーハンミングク拍手応援','2002年日韓ワールドカップで全国を一つにした5拍子の拍手応援法。','「テーハンミングク」と叫んだ後に「パチパチパチ、パチパチ」と続く拍手のリズムが、街頭応援やテレビ中継を通じて全国に広まり、世代や地域を超えた参加型応援文化の象徴となった。','2002年日韓ワールドカップの街頭応援やスタジアム応援で自然発生的に広まった。','団体応援やお祭りの雰囲気を盛り上げたいときに再現しやすい。','なし',array['パチパチパチパチパチ応援','テーハンミングク ファイティン拍手','대~한민국 박수 응원']::text[],'[{"text": "今日みんなでテーハンミングク拍手応援しよう", "situation": "カカオトーク"}, {"text": "このリズム聞くと2002年を思い出す", "situation": "SNSコメント"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('1bf87f2f-ccb2-41fa-a508-34c2326010b4','ja','infinite-challenge-extreme-part-time-job','無限挑戦 極限バイト','メンバーたちが宅配便の仕分けなど過酷なアルバイトを体験した「無限挑戦」の特別編。','2014年11月29日から12月6日まで放送された「無限挑戦」の特別編。EBSのドキュメンタリー「極限職業」をパロディにし、メンバーが1日ずつ過酷なアルバイトを体験した。難易度「下」ではヘビマッサージやコンビニのバイト、「中」ではワニの歯磨きや銭湯掃除、「上」では宅配便の積み下ろし・冷凍倉庫・食肉処理場のバイトが割り当てられた。撮影当日はノ・ホンチョルの代役としてチャ・スンウォンがゲスト出演した。','2014年11月29日、MBC「無限挑戦」の特別編として放送された。','労働の大変さをコミカルに描いた特集として再び注目されている。',null,array['極限バイト特集','무한도전 극한알바']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('1ceefb91-ef11-4bef-92f3-7253c4c16851','ja','han-ttukbaegi-hasillae','トゥッペギ一杯どうですか','芸能人ハイルが訛りたっぷりの方言で言い放った農心「トゥンジ米麺トゥッペギ」のCMコピー。','2009年、農心（ノンシム）はトゥンジ米麺トゥッペギを発売するにあたり、芸能人ハイル（ロバート・ホーリー）をモデルに起用し、「トゥッペギ一杯どうですか」という方言コピーを打ち出した。外国人が話す堂々とした慶尚道方言と字幕なしの発音が数々の誤解と笑いを生み、話題となった。商品自体よりコピーと話し方の方が有名になった事例として、しばしば引き合いに出される。','2009年、農心「トゥンジ米麺トゥッペギ」のテレビCM、ハイル出演。','食べ物を勧めるとき、方言のイントネーションを真似て引用する。',null,array['ロバート・ホーリー米麺','한 뚝배기 하실래예']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('4b3eda59-24ed-4deb-a698-172e8e103191','ja','sg-wannabe-timeless','SGワナビー - Timeless','ミディアムテンポバラードの流行を牽引したSGワナビーの2004年デビュー曲。','2004年に発売されたSGワナビー1集のタイトル曲で、当時流行していたミディアムテンポバラードの中心に立った曲である。デジタル音源プラットフォームで大成功を収め、SGワナビーを一躍スターグループへと押し上げた。','2004年4月、SGワナビーのデビューアルバムのタイトル曲として発売。','2000年代半ばのバラードグループ全盛期を語るときに言及される。',null,array['SGワナビーデビュー曲','SG워너비 - Timeless']::text[],'[{"text": "SGワナビーのTimelessを聴いてたら完全にあの頃のカラオケ感覚だ", "situation": "カカオトーク"}, {"text": "2000年代半ばのバラードといえばやっぱりTimeless", "situation": "SNSコメント"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('50bbc7b0-3526-4b35-a876-f9488cf8510b','ja','lee-daeho-joseon-cleanup-hitter','イ・デホ 朝鮮の4番打者','代表チームで活躍したイ・デホに付けられた流行語ベースのニックネーム。','2006年ドーハ・アジア大会での野球惨敗の際、イ・デホが代表チームで孤軍奮闘したことから、ネットユーザーが当時流行していた「朝鮮の国母だ」というネタをもじって「朝鮮の4番打者」と呼んだ。国民打者の座はすでにイ・スンヨプが占めていたため、別のニックネームを付けたという解釈もある。以後、イ・デホが決定的な場面で活躍するたびにこのニックネームが再び呼び起こされる。','2006年ドーハ・アジア大会以降、野球ファンのコミュニティで広まった。','イ・デホが決定的な場面で活躍したとき「さすが朝鮮の4番打者」と引用される。',null,array['朝鮮の4番打者','이대호 조선의 4번타자']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('5182abeb-8fd1-40de-a4af-d5b926f227c7','ja','damo-does-it-hurt-i-hurt-too','「ダモ」痛いか、私も痛い','2003年のドラマ「ダモ」が残した名台詞。','2003年に放送されたMBCドラマ「ダモ」で、イ・ソジンが負傷したハ・ジウォンにかけた「痛いか、私も痛い」という台詞は、ドラマへの熱心な視聴（通称「ダモ廃人」）とともに、いつまでも語り継がれる名台詞となった。','2003年7月から9月まで放送されたMBCドラマ「ダモ」で、左捕盗庁の従事官ファンボ・ユン（イ・ソジン）が任務中に負傷したチェオク（ハ・ジウォン）に、梅の花が咲き乱れる夜に語りかけた台詞である。抑制された口調で相手の痛みへの共感を表したこの場面は、放送当時、熱心な視聴者を指す「ダモ廃人」という新造語を生むほど話題を呼び、以降も相手を慰めたり共感を示したりする慣用句のように引用され、長く語り継がれている。','相手の痛みに共感するときに引用する。',null,array['다모 아프냐 나도 아프다']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('5e25b26f-90df-452d-b0ee-82c65178d07d','ja','jonbeo-always-wins','ジョンボは勝利する','2018年のビットコイン投資家インタビューの発言が2020年に再び脚光を浴びたミーム。','2018年の放送インタビューで、あるビットコイン投資家が語った「ジョンボは必ず勝利する（我慢して持ち続ければ必ず勝つ）」という言葉が、2020年末にビットコインが急騰したことで予言のように再評価され、再び流行した。','2018年2月、SBS CNBC「経済ワイドイシュー＆」でのビットコイン投資家インタビュー。','耐え抜けば最後には勝つという意味で応援するときに使う。',null,array['ジョンボジャ','ジョンボは必ず勝利する','존버는 승리한다']::text[],'[{"text": "辛くてもジョンボは勝利する、もう少し頑張ろう", "situation": "カカオトーク"}, {"text": "この言葉、まさにジョンボ精神だ", "situation": "SNSコメント"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('6105f91b-ed0e-4120-ae88-c839935afb46','ja','le-sserafim-unforgiven-challenge','LE SSERAFIM「UNFORGIVEN」チャレンジ','LE SSERAFIMの1stフルアルバム収録曲の振り付けを使った2023年のSNSダンスチャレンジ。','2023年5月に発売されたLE SSERAFIMの1stフルアルバム『UNFORGIVEN』収録曲「Eve, Psyche and the Bluebeard''s Wife」の上半身中心の振り付けを使ったチャレンジが流行した。aespaのウィンター、ENHYPENのニキ、SHINeeのキーなど他のアイドルも参加し、歌詞の一部を空けておき参加者が自分で埋める「オープンバースチャレンジ」も同時に行われた。','LE SSERAFIM 1stフルアルバム『UNFORGIVEN』（2023年5月1日発売）のプロモーションチャレンジ。','アイドルの振り付けチャレンジのミームとして使われる。',null,array['アンフォギブンチャレンジ','這うチャレンジ','르세라핌 UNFORGIVEN 챌린지']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('619d1eeb-4831-4999-87d6-52e6d18a64ec','ja','kim-dongmun-ha-taekwon-badminton-doubles-gold','キム・ドンムン、ハ・テグォン バドミントン男子ダブルス金メダル','1997年からペアを組み2004年アテネ五輪男子ダブルスを制したバドミントンダブルス組。','キム・ドンムンとハ・テグォンは1997年からダブルス組として息を合わせ始め、引退するまでずっと一緒に活動した。二人は1999年世界選手権、2000年オールイングランドオープンなど数々の国際大会で優勝し世界ランキング1位に上り詰め、2004年アテネ五輪バドミントン男子ダブルス決勝で同じ韓国選手組を破り金メダルを獲得した。この二人のパートナーシップは韓国バドミントンダブルス全盛期を象徴する事例として挙げられる。','1997〜2004年キム・ドンムン、ハ・テグォンのダブルス組としての活動、2004年アテネ五輪金メダル。','韓国バドミントンダブルスの全盛期の事例として引用される。',null,array['김동문-하태권 배드민턴 복식 금메달']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('64ef7639-f71c-43b2-b3c8-f57b258fd17d','ja','itzy-mafia-in-the-morning-challenge','ITZY「マフィア（Mafia In the morning）」チャレンジ','2021年、ITZYの「마.피.아. In the morning」のカードゲームコンセプトの振り付けチャレンジ。','2021年4月に発売されたITZYのミニアルバムのタイトル曲「마.피.아. In the morning」のポイント振り付けを真似するTikTokチャレンジ。マフィアゲームをモチーフにした神秘的な手の動きとカリスマ性のある表情が特徴で、発売から3週間でミュージックビデオが1億回再生を突破するほど話題となった。','2021年4月の発売直後、TikTokで「in the morning challenge」のハッシュタグとともにカバー映像が拡散した。','ガールクラッシュコンセプトのチャレンジの代表例として言及される。',null,array['ITZY マフィア インザモーニングチャレンジ','있지 마피아(Mafia In the morning) 챌린지']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('6caf1ca3-40ca-40aa-abe3-89fb610d0f21','ja','are-you-t-mbti','君T（ティー）なの？','共感できない人に「MBTIのT型なの？」と尋ねる流行語。','YouTubeのコメディチャンネル「ミムゴリズム」の「フォックスクラブ」シリーズで、撮影者が事実を指摘すると相手が「君T（ティー）なの？」と切り返す場面から、2023年3月に始まった流行語である。相手が共感せず論理的にばかり反応するときにからかうように使う表現で、地上波放送にまで広まった。','YouTubeチャンネル「ミムゴリズム」フォックスクラブシリーズ（2023年3月）の台詞。','相手の共感不足をふざけて指摘するときに使う。','MBTIタイプで人を決めつける表現のため、真剣に使うと反感を買うことがある。',array['お姉さんT型なの','T型なの','너 T야?']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('7c837ac6-15f8-48e7-9a8d-1e0d68ca633e','ja','apt-challenge','「APT.」アパートチャレンジ','ロゼとブルーノ・マーズの「APT.」に登場する韓国の飲み会ゲームを真似する世界的チャレンジ。','2024年10月18日に発売されたロゼとブルーノ・マーズのコラボシングル「APT.」が世界的にヒットしたことで、曲のモチーフとなった韓国式飲み会ゲーム「アパートゲーム」を真似するチャレンジが流行した。参加者が手を積み重ねながら数字を叫び、外れた人が罰ゲームを受ける方式で、韓国の合宿・会食文化がそのまま世界に広まった。TikTokでは史上最短期間で20億回再生を記録した。','ロゼがブルーノ・マーズに韓国の飲み会ゲーム「アパート」を説明したことが曲名の由来となった。2024 MAMAで初めてステージが公開された。','パーティーや集まりで場を盛り上げたいときに言及できる。',null,array['APTチャレンジ','アパートゲームチャレンジ','ロゼ ブルーノマーズ アパート','아파트 챌린지']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('8ca9a12c-c866-48c9-b902-fce76d429fba','ja','sunpoong-sunpoong-sunpoong-ya','スンプン、スンプン、スンプン、ヤー！','シットコム「スンプン産婦人科」の登場人物たちが叫んだ掛け声風の流行語。','SBSの日日シットコム「スンプン産婦人科」の劇中で、登場人物たちが場を盛り上げるために叫んだ掛け声で、シットコムの陽気な雰囲気を象徴する場面としてしばしば語り継がれる。','1998年3月2日から2000年12月1日まで放送されたSBSシットコム「スンプン産婦人科」。','1990年代末〜2000年代初頭のシットコムブームを語るときに引用される。','なし',array['スンプン産婦人科の掛け声','순풍, 순풍, 순풍, 야!']::text[],'[{"text": "スンプン、スンプン、スンプン、ヤー！笑（テンション上がって）", "situation": "カカオトーク"}, {"text": "この掛け声、シットコムブームそのものだ", "situation": "SNSコメント"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('9813bc70-2772-474d-b67a-e7cec560ff08','ja','jojjaejeu-morsinayo','ジョッチェジュ「モルシナヨ」','ダビチの原曲をリメイクした新人ジョッチェジュのデビュー曲がSNSで口コミとなり逆走行ヒット。','ジョッチェジュは2025年1月7日、ダビチの2013年の曲「モルシナヨ」をリメイクしてデビュー曲として発表した。派手なテクニックよりも感情表現を生かしたボーカルがSNSやショート動画のカバー映像を通じて口コミで広まり、発売1〜2週間で反応が出始めて主要音源チャートで逆走行1位となり、2025年上半期のサークルチャート総合7位を記録した。','2025年1月7日、ジョッチェジュがダビチの2013年の曲「モルシナヨ」をリメイクしてデビューし、発売1〜2週間でSNS・ショート動画の口コミにより音源チャートで逆走行1位となった。','エモーショナルなバラードのカバー映像や原曲リメイクの紹介コンテンツに使われる。',null,array['モルシナヨカバー','ダビチ モルシナヨ リメイク','조째즈 모르시나요']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('9d98c75e-5b11-4b41-9fe1-da7ab2130f6e','ja','park-inbee-golden-career-grand-slam','パク・インビ ゴールデンキャリアグランドスラム','キャリアグランドスラムとオリンピック金メダルの両方を達成した世界唯一のゴールデングランドスラム。','パク・インビは2015年の全英女子オープン優勝で、アジア出身選手として初、LPGA史上7人目のキャリアグランドスラムを達成した。翌2016年のリオ五輪ゴルフ女子シングルスでも金メダルを獲得し、男女を通じて世界初の「ゴールデンキャリアグランドスラム」を成し遂げた選手となった。長期間の世界ランキング1位維持や殿堂入りも加わり、ファンからは「ゴルフの女帝」と呼ばれている。','2015年のキャリアグランドスラム達成および2016年リオ五輪金メダル。','韓国女子ゴルフの世界的な地位を語るときに代表的に引用される。',null,array['ゴルフの女帝 パク・インビ','박인비 골든 커리어 그랜드슬램']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('c179f8bb-cb43-447e-ada4-d76f63411855','ja','super-junior-sorry-sorry','SUPER JUNIOR「Sorry, Sorry」','謝るような手の動きの振り付けでアジア全域にカバーダンスブームを起こした曲。','2009年3月に発売されたSUPER JUNIOR3集のタイトル曲「Sorry, Sorry」は、歌詞のように謝っているような手の動きの振り付けが誰でも真似しやすく、10〜20代の間で曲も踊りも流行語のように広まった。韓国のみならず中国・台湾・タイ・フィリピンなどアジア各国の音源チャートを席巻し、世界的なカバーダンスブームを巻き起こした。','SMエンターテインメント SUPER JUNIOR正規3集「Sorry, Sorry」（2009年3月発売）。','2009年のアイドルカバーダンスブームの代表例として言及するときに使う。',null,array['ソリソリダンス','Sorry Sorry振り付け','슈퍼주니어 쏘리쏘리']::text[],'[{"text": "この手の動き完全にソリソリstだ", "situation": "カカオトーク"}, {"text": "カバーダンスブームといえばやっぱりソリソリでしょ", "situation": "SNSコメント"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('c6e86300-b08b-4d0f-8625-e3083113afc6','ja','our-town-music-captain-king-of-mask-singer','「うちの町の音楽隊長」（覆面歌王）','MBC「覆面歌王」で19週連続優勝しシンドロームを起こした覆面歌手キャラクター。','2015年4月に初放送されたMBC「覆面歌王」で2016年初めに登場した「うちの町の音楽隊長」は、独特な挨拶のイントネーションと爆発的な高音で9連勝・19週の長期制覇を記録し、最も話題を集めた覆面歌手となった。正体をめぐりネットユーザーが声や歌唱法を分析し、バンド「グッカステン」のハ・ヒョヌと推測するなど大きな推理ブームを生んだ。','2016年MBC「覆面歌王」に登場した「うちの町の音楽隊長」キャラクター。','バラエティ番組内の正体推理ブームの事例として引用される。',null,array['覆面歌王 音楽隊長','ハ・ヒョヌ 覆面歌王','우리동네 음악대장 (복면가왕)']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('cbf5d5b9-00b6-4603-bdd9-941964944f45','ja','bento-team-great-challenge','ベント号 偉大なる挑戦','ソン・フンミン、キム・ミンジェ、ファン・ヒチャンの負傷危機の中、12年ぶりにアウェイでのベスト16進出を果たしたベント号の軌跡。','パウロ・ベント監督率いる韓国代表は、2022年カタールワールドカップで12月3日にポルトガルを相手に劇的な逆転勝利を収め、12年ぶりとなるアウェイでのベスト16進出を確定させた。主力選手たちの負傷危機の中でも、イ・ジョンヒョプやチョ・ギュソンらの活躍によって成し遂げた成果であり、その後の決勝トーナメント1回戦ではブラジルに1-4で敗れた。この挑戦は「ベント号 偉大なる挑戦」という表現とともに語り継がれ、韓国サッカーの誇らしい瞬間として残っている。','2022年カタールワールドカップ、グループリーグのポルトガル戦での劇的勝利。','2022年ワールドカップにおける韓国代表の感動的なアウェイ・ベスト16進出のストーリーとして引用される。',null,array['2022年カタールワールドカップ ベスト16','벤투호 위대한 도전']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('dea98e3f-3baa-485f-bfe1-7f624621a3fe','ja','mweya','ムェヤ？！','史劇「女人天下」のキョンビン・パク氏の激しい反応が生んだ流行語。','SBS大河史劇「女人天下」でト・ジウォンが演じたキョンビン・パク氏が驚いたり怒ったりしたときに叫んだ「ムェヤ？！」が、様々なバラエティ番組でパロディされるほど大きな人気を集め、史劇流行語の代表的な事例となった。','2001年初めから2002年半ばまで放送されたSBSドラマ「女人天下」。','とんでもない、または呆れるようなニュースに驚いた反応として引用される。','なし',array['女人天下 ムェヤ','뭬야?!']::text[],'[{"text": "ムェヤ？！本当なの？", "situation": "カカオトーク"}, {"text": "この反応完全にキョンビン・パクstだ", "situation": "SNSコメント"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('df2d0c0c-de1e-41ab-8888-b16deb8faba7','ja','tv-carries-love','TVは愛を乗せて','1994年に始まった、知人を探す感動系バラエティ番組。','1994年5月に始まったKBS「TVは愛を乗せて」は、有名人が長年会えずにいる知人を探し出し再会させる形式で、スタジオのドアが開き再会する瞬間の感動によって大きな人気を集め、1997年頃に全盛期を迎えた。','「TVは愛を乗せて」は1994年5月3日に始まり2010年まで通算805回放送されたKBSの時事教養・バラエティ番組で、制作陣が有名人の初恋の相手・恩師・同窓生などの知人を探し出す形式で構成された。依頼人と知人の昔のエピソードを無名俳優が再現し、キム・ジョンファン、チャン・ヘソン、その後キム・イルらのナレーションが感動を添える構成が人気を集め、1997年頃には話題性・視聴率ともに絶頂を迎えた。知人を探すリアリティ形式の元祖的な番組として長く放送され、世代を超えた人気を得た。','長年の知人との感動的な再会を語るときの事例として言及できる。',null,array['TV는 사랑을 싣고']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
